function profit(price, variable, fixed, units) {
  return price * units - (fixed + variable * units);
}

function unitsToCover(fixed, margin) {
  return fixed / margin;
}

function remainingBalance(total, months, elapsed) {
  return total - (total / months) * elapsed;
}

function marginPercent(revenue, cost) {
  return ((revenue - cost) / revenue) * 100;
}

function breakEvenUnits(fixed, price, variable) {
  const margin = price - variable;
  if (margin <= 0) return Infinity;
  return Math.ceil(fixed / margin);
}

function remainingAfter(total, months, elapsed) {
  if (months <= 0) throw new Error("months must be positive");
  if (elapsed >= months) return 0;
  return total - (total / months) * elapsed;
}

function losingSegments(fixed, segments) {
  const totalUsers = segments.reduce((sum, s) => sum + s.users, 0);
  return segments
    .filter((s) => {
      const share = fixed * (s.users / totalUsers);
      const cost = share + s.variablePerUser * s.users;
      const revenue = s.price * s.users;
      return revenue < cost;
    })
    .map((s) => s.name);
}

function breakEvenPrice(fixed, variable, units) {
  if (units <= 0) throw new Error("units must be positive");
  return fixed / units + variable;
}
